import { PHOTO } from "~/lib/catalog/photos";

/** Widths generated by scripts/photos.mjs into public/photos/w/<key>-<w>.webp. */
const WIDTHS = [480, 800, 1200, 1600, 2000];

/**
 * A photograph from the house library, by key, filling a sized relative parent.
 * Serves the WebP width variants in a srcset; the original JPEG is the fallback src.
 * When photography moves to Shopify Files this becomes a CDN srcset with the same props.
 */
export function Pic({
  k,
  sizes = "100vw",
  priority = false,
  className = "",
  position,
}: {
  k: string;
  sizes?: string;
  priority?: boolean;
  className?: string;
  position?: string;
}) {
  const p = PHOTO[k] ?? PHOTO["hero-box"];
  const key = p.src.replace(/^\/photos\//, "").replace(/\.\w+$/, "");
  const widths = WIDTHS.filter((w) => w <= p.w);
  const srcSet = widths.length ? widths.map((w) => `/photos/w/${key}-${w}.webp ${w}w`).join(", ") : undefined;
  return (
    <img
      src={p.src}
      srcSet={srcSet}
      alt={p.alt}
      width={p.w}
      height={p.h}
      sizes={sizes}
      loading={priority ? "eager" : "lazy"}
      fetchPriority={priority ? "high" : undefined}
      decoding={priority ? "sync" : "async"}
      className={`absolute inset-0 h-full w-full object-cover ${className}`}
      style={position ? { objectPosition: position } : undefined}
    />
  );
}
